INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～んですか', 'Hỏi xác nhận thông tin / Hỏi lý do, nguyên nhân', 'Thể thường ～んですか。 (Aな/N だ→な)', '- Xác nhận lại thông tin với những điều nhìn thấy, nghe thấy…
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '雨が降っているんですか。', 'あめがふっているんですか。', 'Trời đang mưa à?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND g.pattern = '～んですか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '雨が降っているんですか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '[これは]どこで買ったんですか。', '[これは]どこでかったんですか。', '(Cái này) mua ở đâu vậy?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND g.pattern = '～んですか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '[これは]どこで買ったんですか。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'A：「どうして掃除しないんですか。」', 'A：「どうしてそうじしないんですか。」', 'Tại sao lại không dọn dẹp vậy?', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND g.pattern = '～んですか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'A：「どうして掃除しないんですか。」' AND ge2.sort_order = 3);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'B：「時間がないんです。」(không kèm theo から)', 'B：「じかんがないんです。」', 'Vì không có thời gian.', NULL, 4 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND g.pattern = '～んですか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'B：「時間がないんです。」(không kèm theo から)' AND ge2.sort_order = 4);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～んですが、～Vていただけませんか', 'Đưa ra vấn đề rồi nhờ vả đối phương một cách lịch sự', 'Thể thường ～んですが、～Vていただけませんか。 (Aな/N だ→な)', 'Đưa ra vấn đề rồi nhờ vả đối phương. Lịch sự hơn so với Vてください。', 'Lịch sự hơn Vてください', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～んですが、～Vていただけませんか');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'わからないんですが、ゆっくり話していただけませんか。', 'わからないんですが、ゆっくりはなしていただけませんか。', 'Tôi không hiểu nên làm ơn hãy nói chậm lại.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND g.pattern = '～んですが、～Vていただけませんか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'わからないんですが、ゆっくり話していただけませんか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '生け花を習いたいんですが、いい先生を紹介していただけませんか。', 'いけばなをならいたいんですが、いいせんせいをしょうかいしていただけませんか。', 'Tôi muốn học cắm hoa, làm ơn hãy giới thiệu giáo viên tốt giúp tôi.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND g.pattern = '～んですが、～Vていただけませんか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '生け花を習いたいんですが、いい先生を紹介していただけませんか。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～んですが、～Vたらいいですか', 'Đưa ra vấn đề rồi sau đó xin lời khuyên từ đối phương', 'Thể thường ＋んですが、Từ nghi vấn + Vたらいいですか。 (Aな/N だ→な)', 'Đưa ra vấn đề rồi sau đó xin lời khuyên từ đối phương.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～んですが、～Vたらいいですか');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'コピー機がこしょうなんですが、どこに連絡したらいいですか。', 'コピーきがこしょうなんですが、どこにれんらくしたらいいですか。', 'Máy photo bị hỏng, tôi nên liên lạc tới đâu thì tốt nhỉ?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND g.pattern = '～んですが、～Vたらいいですか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'コピー機がこしょうなんですが、どこに連絡したらいいですか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '日本人のうちへ行くんですが、どんなお土産を持って行ったらいいですか。', 'にほんじんのうちへいくんですが、どんなおみやげをもっていったらいいですか。', 'Tôi sẽ đi đến nhà của người Nhật, vậy nên mang theo quà gì thì tốt nhỉ?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND g.pattern = '～んですが、～Vたらいいですか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '日本人のうちへ行くんですが、どんなお土産を持って行ったらいいですか。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～可能形（かのうけい）', 'Thể khả năng (có thể làm ~)', 'Nhóm 1: ～iます → ～eます
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'さくらちゃんはピアノが弾けます。', 'さくらちゃんはピアノがひけます。', 'Bé Sakura có thể chơi được Piano.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = '～可能形（かのうけい）' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'さくらちゃんはピアノが弾けます。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'この銀行でドルが換えられます。', 'このぎんこうでドルがかえられます。', 'Có thể đổi đô-la ở ngân hàng này.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = '～可能形（かのうけい）' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'この銀行でドルが換えられます。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '見えます・聞こえます', 'Nhìn thấy / Nghe thấy (tự nhiên lọt vào tầm mắt, tai)', '～が見えます。／～が聞こえます。', 'Diễn tả việc có thể nhìn thấy, nghe thấy vì đối tượng lọt vào tầm mắt, vào tai một cách tự nhiên mà không phụ thuộc vào chủ ý của người nói.', 'Khác với 見られます (có điều kiện để xem) và 聞けます (có điều kiện để nghe).', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '見えます・聞こえます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ここから富士山が見えます。', 'ここからふじさんがみえます。', 'Từ đây có thể thấy được núi Phú Sĩ.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = '見えます・聞こえます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ここから富士山が見えます。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私の声が聞こえますか？', 'わたしのこえがきこえますか？', 'Có nghe thấy tiếng tôi không thế?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = '見えます・聞こえます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私の声が聞こえますか？' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Nができます', '~ được hoàn thiện / hoàn thành / xây xong', 'Nができます。', '~ được hoàn thiện/ hoàn thành, được xây dựng xong hoặc làm xong.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Nができます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '駅の前にコンビニができました。', 'えきのまえにコンビニができました。', 'Trước nhà ga có cửa hàng tiện lợi được hoàn thành.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = 'Nができます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '駅の前にコンビニができました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '時計の修理はいつできますか。', 'とけいのしゅうりはいつできますか。', 'Việc sửa đồng hồ khi nào sẽ xong?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = 'Nができます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '時計の修理はいつできますか。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～しか～', 'Chỉ có mỗi… (vế sau đi với phủ định)', 'N ＋ しか [～ない]。', 'Chỉ có mỗi… Đứng sau danh từ, lượng từ… Vế sau luôn đi với dạng phủ định mang sắc thái tiếc nuối, không đủ.', 'Luôn đi kèm với động từ dạng phủ định', 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～しか～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '水しか飲みません。', 'みずしかのみません。', 'Tôi chỉ uống nước lọc.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = '～しか～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '水しか飲みません。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ひらがなしか読めません。', 'ひらがなしかよめません。', 'Tôi chỉ có thể đọc được chữ Hiragana.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = '～しか～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ひらがなしか読めません。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'N1は～が、N2は～', 'N1 thì… còn N2 thì… (đối sánh)', 'N1は～が、N2は～。', 'N1 thì… còn N2 thì… Biểu thị sự đối sánh giữa N1 và N2.', NULL, 5 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'N1は～が、N2は～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'サッカーはしますが、やきゅうはしません。', 'サッカーはしますが、やきゅうはしません。', 'Bóng đá thì chơi còn bóng chày thì không chơi.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = 'N1は～が、N2は～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'サッカーはしますが、やきゅうはしません。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ラーメンは好きですが、うどんは好きじゃありません。', 'ラーメンはすきですが、うどんはすきじゃありません。', 'Ramen thì thích còn udon thì không thích.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND g.pattern = 'N1は～が、N2は～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ラーメンは好きですが、うどんは好きじゃありません。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'V１ながら、V2ます', 'Vừa làm V1 vừa làm V2', 'V１(bỏ ます) ＋ ながら、V2ます。', 'Hai hành động (thực hiện bởi cùng một chủ thể) diễn ra song song trong thời gian ngắn hoặc dài. V2 là hành động chính.', 'Cùng một chủ thể thực hiện cả hai hành động. V2 là hành động chính.', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'V１ながら、V2ます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '本を読みながら、おふろに入ります。', 'ほんをよみながら、おふろにはいります。', 'Vừa đọc sách vừa tắm bồn.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND g.pattern = 'V１ながら、V2ます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '本を読みながら、おふろに入ります。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '運転しながら、電話をしないでください。', 'うんてんしながら、でんわをしないでください。', 'Đừng vừa lái xe vừa gọi điện thoại.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND g.pattern = 'V１ながら、V2ます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '運転しながら、電話をしないでください。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'アルバイトをしながら、大学で勉強します。', 'アルバイトをしながら、だいがくでべんきょうします。', 'Vừa học đại học vừa làm thêm.', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND g.pattern = 'V１ながら、V2ます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'アルバイトをしながら、大学で勉強します。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Vています', 'Thường làm… (thói quen, hành động lặp đi lặp lại)', 'Vています。 (Thói quen trong quá khứ: Vていました。)', 'Thường làm… Diễn tả hành động lặp đi lặp lại theo thói quen. Thói quen trong quá khứ dùng Vていました。', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vています');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'いつも遅くまで勉強しています。', 'いつもおそくまでべんきょうしています。', 'Tôi thường học tới muộn.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND g.pattern = 'Vています' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'いつも遅くまで勉強しています。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '毎日、食べてから、新聞を読んでいます。', 'まいにち、たべてから、しんぶんをよんでいます。', 'Hàng ngày sau khi ăn, tôi thường đọc báo.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND g.pattern = 'Vています' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '毎日、食べてから、新聞を読んでいます。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '子どもの時、友達とつりをしていました。', 'こどものとき、ともだちとつりをしていました。', 'Hồi nhỏ, tôi thường câu cá với bạn bè.', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND g.pattern = 'Vています' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '子どもの時、友達とつりをしていました。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～し、～し', 'Vừa… lại vừa… / Vì… và vì… nên… (liệt kê lý do)', 'Thể thường ＋し、Thể thường ＋し、～。 (Aな/N だ→だし)', 'Liệt kê các nguyên nhân, lý do (từ 2 lý do trở lên) dẫn tới kết quả ở vế sau.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～し、～し');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '雨も降っているし、お金もないし、どこへも行きません。', 'あめもふっているし、おかねもないし、どこへもいきません。', 'Trời vừa mưa lại vừa không có tiền nên chẳng đi đâu cả.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND g.pattern = '～し、～し' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '雨も降っているし、お金もないし、どこへも行きません。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '彼は親切だし、頭もいいし、それにハンサムです。', 'かれはしんせつだし、あたまもいいし、それにハンサムです。', 'Anh ấy vừa tốt bụng, vừa thông minh, hơn nữa lại còn đẹp trai.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 28 AND g.pattern = '～し、～し' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '彼は親切だし、頭もいいし、それにハンサムです。' AND ge2.sort_order = 2);
