INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'NがVています', 'N đang trong trạng thái V (kết quả của tự động từ)', 'N が V(tự động từ)ています。', 'Diễn tả trạng thái của sự vật hiện hữu trước mắt người nói, là kết quả của một hành động đã xảy ra.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 29 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'NがVています');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '窓が割れています。', 'まどがわれています。', 'Cửa sổ bị vỡ.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 29 AND g.pattern = 'NがVています' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '窓が割れています。' AND ge2.sort_order = 1);
