(2) Thể hiện sự tiếc nuối, hối hận về một việc đã lỡ xảy ra ngoài ý muốn.', NULL, 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 29 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vてしまいます');
