INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '電車にかさを忘れてしまいました。', 'でんしゃにかさをわすれてしまいました。', 'Tôi lỡ để quên ô trên tàu điện rồi.', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 29 AND g.pattern = 'Vてしまいます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '電車にかさを忘れてしまいました。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'N(địa điểm)に～がVてあります', 'Ở địa điểm N có vật ~ đang (được làm sẵn)', 'N(địa điểm) に ～ が V(tha động từ)てあります。', 'Diễn tả trạng thái hiện tại của một vật, là kết quả đã phát sinh do một hành động có chủ ý của ai đó. Mẫu câu này sử dụng tha động từ.', 'Ở địa điểm N có vật ~ đang ~', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 30 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'N(địa điểm)に～がVてあります');
