INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'たなの上に人形がかざってあります。', 'たなのうえににんぎょうがかざってあります。', 'Trên giá có trang trí búp bê.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 30 AND g.pattern = 'N(địa điểm)に～がVてあります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'たなの上に人形がかざってあります。' AND ge2.sort_order = 2);
