INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '飲み物は冷蔵庫においてあります。', 'のみものはれいぞうこにおいてあります。', 'Đồ uống được để trong tủ lạnh.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 30 AND g.pattern = '～はN(địa điểm)にVてあります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '飲み物は冷蔵庫においてあります。' AND ge2.sort_order = 1);
