INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Vますなさい', 'Hãy làm V (mệnh lệnh nhẹ nhàng)', 'Vます(bỏ ます) ＋ なさい。', 'Hãy làm V. Đây là mẫu câu mệnh lệnh nhưng có sắc thái nhẹ nhàng hơn so với thể mệnh lệnh, thường dùng khi bố mẹ nói với con cái, giáo viên nói với học sinh.', 'Thường dùng bởi bố mẹ nói với con cái, giáo viên nói với học sinh', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vますなさい');
