INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～と書いてあります/～と読みます', 'Được viết là ~ / Được đọc là ~', '～と書いてあります / ～と読みます。', 'Dùng khi miêu tả nội dung được viết ở đâu đó hay cách đọc của một từ, ký hiệu, chữ Hán… Dạng câu hỏi: 何と書いてありますか。／何と読みますか。', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～と書いてあります/～と読みます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'すみません。これは何と読みますか。', 'すみません。これはなんとよみますか。', 'Xin lỗi, cái này đọc như thế nào vậy?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND g.pattern = '～と書いてあります/～と読みます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'すみません。これは何と読みますか。' AND ge2.sort_order = 1);
