INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'あそこに「きんえん」と書いてあります。', 'あそこに「きんえん」とかいてあります。', 'Đằng kia có viết là “Cấm hút thuốc”.', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND g.pattern = '～と書いてあります/～と読みます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'あそこに「きんえん」と書いてあります。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'AはBという意味です', 'A có nghĩa là B', 'AはBという意味です。', 'Dùng để giải thích ý nghĩa của từ/câu/biển báo... Dạng câu hỏi: Aはどういう意味ですか。', NULL, 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'AはBという意味です');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'あれはどういう意味ですか。', 'あれはどういういみですか。', 'Cái kia có nghĩa là gì vậy?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND g.pattern = 'AはBという意味です' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'あれはどういう意味ですか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '左へ曲がるなという意味です。', 'ひだりへまがるなといういみです。', 'Có nghĩa là cấm rẽ trái.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND g.pattern = 'AはBという意味です' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '左へ曲がるなという意味です。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～と言っていました', 'Ai đó nói ~/ nhắn là ~ (truyền đạt lại lời nhắn)', '「Câu」/ Thể thông thườngと言っていました。', 'Dùng khi truyền đạt lại lời nhắn của ai đó (ngôi thứ ba). Dạng câu hỏi: 何と言っていましたか。', NULL, 5 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～と言っていました');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ミラーさんは何と言っていましたか。', 'ミラーさんはなんといっていましたか。', 'Anh Mira đã nói gì vậy?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND g.pattern = '～と言っていました' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ミラーさんは何と言っていましたか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '2時に会議室にいると言っていました。', '2じにかいぎしつにいるといっていました。', '(Anh ấy) đã nói là có ở phòng họp lúc 2 giờ.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND g.pattern = '～と言っていました' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '2時に会議室にいると言っていました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～と伝えていただけませんか', 'Nhắn lại (cho ai đó) giúp tôi rằng… được không?', '「Câu」/ Thể thông thườngと伝えていただけませんか。', 'Nhờ người khác truyền đạt lại thông tin một cách lịch sự.', NULL, 6 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～と伝えていただけませんか');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ワンさんにもうすぐ来ると伝えていただけませんか。', 'ワンさんにもうすぐくるとつたえていただけませんか。', 'Hãy nhắn với anh Wang rằng tôi sắp sửa tới rồi được không?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND g.pattern = '～と伝えていただけませんか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ワンさんにもうすぐ来ると伝えていただけませんか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'リンさんに「レポートを送ってください」と伝えていただけませんか。', 'リンさんに「レポートをおくってください」とつたえていただけませんか。', 'Làm ơn nhắn với chị Linh là hãy gửi báo cáo giúp tôi có được không?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND g.pattern = '～と伝えていただけませんか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'リンさんに「レポートを送ってください」と伝えていただけませんか。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～とおりに、～', 'Làm theo như ~', 'V１た/Nの＋とおりに、V2。', 'Làm V2 theo như động tác V1 hoặc hướng dẫn N. Khi V1 là hành động mang tính dự định, hoặc chưa xảy ra, V1 nói “hãy làm theo đúng như (sẽ) làm”.', NULL, 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～とおりに、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私が言ったとおりに、やってください。', 'わたしがいったとおりに、やってください。', 'Hãy làm theo những gì tôi đã nói.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND g.pattern = '～とおりに、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私が言ったとおりに、やってください。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '地図のとおりに、行ってください。', 'ちずのとおりに、いってください。', 'Hãy đi theo bản đồ.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND g.pattern = '～とおりに、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '地図のとおりに、行ってください。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'このとおりに、書いてください。', 'このとおりに、かいてください。', 'Hãy viết đúng thế này.', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND g.pattern = '～とおりに、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'このとおりに、書いてください。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～あとで、～', 'Sau khi ~', 'V１た/Nの＋あとで、V2。', 'Hành động V2 diễn ra sau hành động V1 hoặc sau sự việc N.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～あとで、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '仕事のあとで、飲みに行きます。', 'しごとのあとで、のみにいきます。', 'Sau khi làm việc xong, tôi sẽ đi uống nước.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND g.pattern = '～あとで、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '仕事のあとで、飲みに行きます。' AND ge2.sort_order = 1);
