INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～て/ないで', 'Làm V2 trong trạng thái V1', 'V１て/V１ないで、V2。', 'Làm V2 (hành động chính) trong trạng thái đi kèm V1.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～て/ないで');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'しょうゆをつけて、食べます。', 'しょうゆをつけて、たべます。', 'Chấm xì dầu rồi ăn.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND g.pattern = '～て/ないで' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'しょうゆをつけて、食べます。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '砂糖を入れないで、コーヒーを飲みます。', 'さとうをいれないで、コーヒーをのみます。', 'Uống cà phê mà không cho đường.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND g.pattern = '～て/ないで' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '砂糖を入れないで、コーヒーを飲みます。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～ないで、～', 'Không làm V1 mà làm V2 (thay thế)', 'V１ないで、V2。', 'Không làm hành động V1 mà lại làm hành động V2 (thay thế).', NULL, 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～ないで、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'テレビを見ないで、音楽を聞きました。', 'テレビをみないで、おんがくをききました。', 'Tôi đã nghe nhạc thay vì xem tivi.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND g.pattern = '～ないで、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'テレビを見ないで、音楽を聞きました。' AND ge2.sort_order = 1);
