INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '条件形（～ば／なら）、～', 'Nếu… thì… (nêu điều kiện)', 'Điều kiện (～ば／なら）、Mệnh đề kết quả。', 'Nêu điều kiện cần thiết để sự việc nào đó xảy ra. Vế 1: Chia về thể điều kiện. Vế 2: Sự việc, mệnh đề.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '条件形（～ば／なら）、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '暑ければ、泳ぎに行きます。', 'あつければ、およぎにいきます。', 'Nếu trời nóng, tôi sẽ đi bơi.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND g.pattern = '条件形（～ば／なら）、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '暑ければ、泳ぎに行きます。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '薬を飲めば、風邪が治りますよ。', 'くすりをのめば、かぜがなおりますよ。', 'Nếu uống thuốc thì sẽ khỏi cảm cúm đấy.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND g.pattern = '条件形（～ば／なら）、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '薬を飲めば、風邪が治りますよ。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～ばいいですか', 'Nên làm thế nào thì được? (xin lời khuyên)', 'Từ để hỏi + Vばいいですか。', 'Mong muốn đối phương hướng dẫn, đưa ra lời khuyên để làm việc gì đó. Dùng tương tự mẫu câu 「～たらいいですか。」', 'Tương tự ～たらいいですか', 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～ばいいですか');
