INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '父の誕生日に何を買えばいい？', 'ちちのたんじょうびになにをかえばいい？', 'Tôi nên mua gì vào ngày sinh nhật bố nhỉ?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND g.pattern = '～ばいいですか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '父の誕生日に何を買えばいい？' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Nなら、～', 'Nếu là N thì ~ (đưa ra lời khuyên/thông tin về chủ đề)', 'Nなら、～', 'Cung cấp thông tin nào đó liên quan đến N (chủ đề) mà đối phương vừa đề cập đến.', NULL, 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Nなら、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'A: 旅行したいんです、どごへ行けばいいでしょうか。', 'A: りょこうしたいんです、どこへいけばいいでしょうか。', 'Tôi muốn đi du lịch thì nên đi đâu được nhỉ?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND g.pattern = 'Nなら、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'A: 旅行したいんです、どごへ行けばいいでしょうか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'B: 旅行なら、ハワイがいいですよ。', 'B: りょこうなら、ハワイがいいですよ。', 'Nếu mà du lịch thì Hawaii được đấy.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND g.pattern = 'Nなら、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'B: 旅行なら、ハワイがいいですよ。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Vる／Vないように、～', 'Để (có thể/không) ~, thì ~ (chỉ mục đích)', 'Vる／Vない ＋ ように、～', 'Chỉ mục đích của hành động ở vế sau. Vế 1 thường là động từ khả năng, tự động từ hoặc thể phủ định.', 'Vế 1 là động từ không có ý chí (khả năng, tự động từ, phủ định)', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vる／Vないように、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '日本語が話せるように、毎日練習します。', 'にほんごがはなせるように、まいにちれんしゅうします。', 'Để có thể nói tiếng Nhật, tôi luyện tập mỗi ngày.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND g.pattern = 'Vる／Vないように、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '日本語が話せるように、毎日練習します。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '風邪を引かないように、気をつけてください。', 'かぜをひかないように、きをつけてください。', 'Hãy cẩn thận để không bị cảm.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND g.pattern = 'Vる／Vないように、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '風邪を引かないように、気をつけてください。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Vるように＋なります', 'Trở nên có thể làm / Đã biết làm ~ (biến đổi trạng thái)', 'V(khả năng)るように＋なります / V(khả năng)なくなります', 'Biểu thị sự biến đổi trạng thái từ không thể sang có thể (hoặc ngược lại).', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vるように＋なります');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '日本語の新聞が読めるようになりました。', 'にほんごのしんぶんがよめるようになりました。', 'Tôi đã có thể đọc được báo tiếng Nhật.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND g.pattern = 'Vるように＋なります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '日本語の新聞が読めるようになりました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '刺身が食べられるようになりました。', 'さしみがたべられるようになりました。', 'Tôi đã có thể ăn được món Sashimi.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND g.pattern = 'Vるように＋なります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '刺身が食べられるようになりました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Vる・Vないように します', 'Cố gắng làm / Cố gắng không làm ~ (thói quen, nỗ lực)', 'Vる／Vない ＋ ように します (nhắc nhở: ように してください)', 'Thể hiện sự nỗ lực, cố gắng duy trì một thói quen hoặc hành vi có ý thức.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vる・Vないように します');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '毎日野菜を食べるようにしています。', 'まいにちやさいをたべるようにしています。', 'Hàng ngày tôi cố gắng ăn rau.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND g.pattern = 'Vる・Vないように します' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '毎日野菜を食べるようにしています。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '甘いものを食べないようにしています。', 'あまいものをたべないようにしています。', 'Tôi cố gắng không ăn đồ ngọt.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND g.pattern = 'Vる・Vないように します' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '甘いものを食べないようにしています。' AND ge2.sort_order = 2);
