INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'N1は N2に V受身形', 'N1 bị/được N2 làm gì (bị động trực tiếp)', 'N1(người nhận) は N2(người làm) に V(bị động)。', 'Câu bị động trực tiếp: Người nhận hành động đóng vai trò chủ ngữ.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'N1は N2に V受身形');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私は先生に褒められました。', 'わたしはせんせいにほめられました。', 'Tôi được thầy giáo khen.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND g.pattern = 'N1は N2に V受身形' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私は先生に褒められました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私は犬にかまれました。', 'わたしはいぬにかまれました。', 'Tôi bị chó cắn.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND g.pattern = 'N1は N2に V受身形' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私は犬にかまれました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'N1はN2にN3をV受身形', 'N1 bị N2 làm gì đối với N3 (bị động gián tiếp / quấy rầy)', 'N1 は N2 に N3 を V(bị động)。', 'Bị động gián tiếp: Thường diễn tả việc người nói bị phiền toái, thiệt hại khi ai đó làm gì với đồ vật/thân thể của mình.', 'Thể hiện cảm giác bị làm phiền, thiệt hại', 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'N1はN2にN3をV受身形');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '弟にパソコンを壊されました。', 'おとうとにパソコンをこわされました。', 'Tôi bị em trai làm hỏng máy tính.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND g.pattern = 'N1はN2にN3をV受身形' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '弟にパソコンを壊されました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '泥棒にお金を盗まれました。', 'どろぼうにおかねをぬすまれました。', 'Tôi bị trộm lấy mất tiền.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND g.pattern = 'N1はN2にN3をV受身形' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '泥棒にお金を盗まれました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Nは／が V受身形', 'Vật N được làm / xây dựng / phát minh (không nêu tác nhân)', 'N は／が V(bị động)。', 'Dùng khi miêu tả sự việc, công trình kiến trúc, phát minh mà không cần nhấn mạnh người thực hiện.', NULL, 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Nは／が V受身形');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'このビルは2000年に建てられました。', 'このビルは2000ねんにたてられました。', 'Tòa nhà này được xây vào năm 2000.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND g.pattern = 'Nは／が V受身形' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'このビルは2000年に建てられました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '電話はベルによって発明されました。', 'でんわはベルによってはつめいされました。', 'Điện thoại được phát minh bởi Bell.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND g.pattern = 'Nは／が V受身形' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '電話はベルによって発明されました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～から／～でつくられます', 'Được làm từ ~ (vật liệu: で / nguyên liệu: から)', 'N で／から つくられます。', 'Dùng で khi vật liệu không bị biến đổi về chất (vẫn nhận ra bằng mắt thường). Dùng から khi nguyên liệu bị biến đổi về chất.', 'で: vật liệu (gỗ, sắt...) / から: nguyên liệu (lúa mạch, nho...)', 5 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～から／～でつくられます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'この机は木で作られています。', 'このつくえはきでつくられています。', 'Cái bàn này được làm từ gỗ.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND g.pattern = '～から／～でつくられます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'この机は木で作られています。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ビールは麦から作られます。', 'ビールはむぎからつくられます。', 'Bia được làm từ lúa mạch.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND g.pattern = '～から／～でつくられます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ビールは麦から作られます。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'VるのはA です', 'Việc làm V thì mang tính chất A', 'Vる ＋ のは A です。', 'Danh từ hóa động từ bằng 「の」 để làm chủ ngữ trong câu tính từ miêu tả tính chất (thú vị, vất vả, vui...).', NULL, 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'VるのはA です');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'テニスをするのは面白いです。', 'テニスをするのはおもしろいです。', 'Chơi tennis rất thú vị.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'VるのはA です' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'テニスをするのは面白いです。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '一人で外国へ旅行するのは大変です。', 'ひとりでがいこくへりょこうするのはたいへんです。', 'Đi du lịch nước ngoài một mình rất vất vả.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'VるのはA です' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '一人で外国へ旅行するのは大変です。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'VるのがAです', 'Thích / Ghét / Giỏi / Kém việc làm V', 'Vる ＋ のが A(好き/嫌い/上手/下手/速い/遅い) です。', 'Dùng 「のが」 với các tính từ chỉ sở thích, sở ghét, năng lực hoặc tốc độ.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'VるのがAです');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私は絵を描くのが好きです。', 'わたしはえをかくのがすきです。', 'Tôi thích vẽ tranh.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'VるのがAです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私は絵を描くのが好きです。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '彼は走るのが速いです。', 'かれははしるのがはやいです。', 'Anh ấy chạy rất nhanh.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'VるのがAです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '彼は走るのが速いです。' AND ge2.sort_order = 2);
