INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '薬を飲むのを忘れました。', 'くすりをのむのをわすれました。', 'Tôi quên uống thuốc rồi.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'Vるのをわすれます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '薬を飲むのを忘れました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'かぎをかけるのを忘れました。', 'かぎをかけるのをわすれました。', 'Tôi quên khóa cửa rồi.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'Vるのをわすれます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'かぎをかけるのを忘れました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'V(thể thường)のをしっていますか', 'Bạn có biết việc ~ không?', 'Thể thường ＋ のを知っていますか。 (Aな/N だ→な)', 'Hỏi xem đối phương có biết thông tin, sự việc nào đó không.', NULL, 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'V(thể thường)のをしっていますか');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ミラーさんが結婚したのを知っていますか。', 'ミラーさんがけっこんしたのをしっていますか。', 'Bạn có biết anh Miller đã kết hôn không?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'V(thể thường)のをしっていますか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ミラーさんが結婚したのを知っていますか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '明日テストがあるのを知っていますか。', 'あしたテストがあるのをしっていますか。', 'Bạn có biết ngày mai có bài kiểm tra không?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'V(thể thường)のをしっていますか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '明日テストがあるのを知っていますか。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Thể thườngのはNです', 'Cái / Nơi / Người mà ~ chính là N', 'Thể thường ＋ のは N です。 (Aな/N だ→な)', 'Nhấn mạnh đối tượng N (thời gian, địa điểm, con người, sự vật) ở vị ngữ.', NULL, 5 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Thể thườngのはNです');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私が生まれたのは北海道です。', 'わたしがうまれたのはほっかいどうです。', 'Nơi tôi sinh ra là Hokkaido.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'Thể thườngのはNです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私が生まれたのは北海道です。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '彼が好きなのは音楽です。', 'かれがすきなのはおんがくです。', 'Thứ anh ấy thích là âm nhạc.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND g.pattern = 'Thể thườngのはNです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '彼が好きなのは音楽です。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～て、～', 'Vì… nên… (chỉ nguyên nhân tự nhiên, cảm xúc, không ý chí)', 'Vて／Vなくて／Aくて／Aで、～', 'Vế 1 là nguyên nhân dẫn đến kết quả ở vế 2. Vế 2 thường là cảm xúc, khả năng hoặc sự việc tự nhiên, không dùng câu mệnh lệnh, ý chí, rủ rê.', 'Vế sau không dùng câu nhờ vả, mệnh lệnh, rủ rê', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～て、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ニュースを聞いて、びっくりしました。', 'ニュースをきいて、びっくりしました。', 'Nghe tin tức xong tôi giật mình.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND g.pattern = '～て、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ニュースを聞いて、びっくりしました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '家族に会えなくて、寂しいです。', 'かぞくにあえなくて、さびしいです。', 'Không gặp được gia đình nên thấy buồn.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND g.pattern = '～て、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '家族に会えなくて、寂しいです。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Nで～', 'Do / Vì N (thiên tai, tai nạn, sự cố...)', 'N(thiên tai, tai nạn, dịch bệnh) で、～', 'Danh từ chỉ nguyên nhân khách quan như bão, động đất, hỏa hoạn, tai nạn giao thông dẫn đến kết quả ở vế sau.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Nで～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '地震でビルが倒れました。', 'じしんでビルがたおれました。', 'Do động đất nên tòa nhà bị sập.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND g.pattern = 'Nで～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '地震でビルが倒れました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '事故で電車が止まりました。', 'じこででんしゃがとまりました。', 'Do tai nạn nên tàu điện bị dừng.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND g.pattern = 'Nで～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '事故で電車が止まりました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～ので、～', 'Vì… nên… (lý do khách quan, lịch sự)', 'Thể thường ＋ ので、～。 (Aな/N だ→な)', 'Nêu lý do khách quan, nhẹ nhàng và lịch sự hơn から. Thường dùng khi xin phép, nhờ vả, giải thích lý do giao tiếp lịch sự.', 'Lịch sự và khách quan hơn から', 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～ので、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '用事があるので、お先に失礼します。', 'ようじがあるので、おさきにしつれいします。', 'Vì có việc bận nên tôi xin phép về trước.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND g.pattern = '～ので、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '用事があるので、お先に失礼します。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '気分が悪いので、少し休んでもいいですか。', 'きぶんがわるいので、すこしやすんでもいいですか。', 'Vì thấy không khỏe nên tôi nghỉ một chút được không?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND g.pattern = '～ので、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '気分が悪いので、少し休んでもいいですか。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～か、～', 'Lồng câu nghi vấn có từ để hỏi vào câu khác', 'Thể thường ＋ か、～。 (Aな/N だ bỏ だ)', 'Lồng câu nghi vấn chứa từ để hỏi vào trong câu văn khác.', NULL, 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～か、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ビールは何本あるか、数えてください。', 'ビールはなんぼんあるか、かぞえてください。', 'Hãy đếm xem có bao nhiêu chai bia.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND g.pattern = '～か、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ビールは何本あるか、数えてください。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'A：二次会はどこへ行きましたか？ B：酔っていたので、どこへ行ったか、全然覚えていないんです。', 'A：にじかいはどこへいきましたか？ B：よっていたので、どこへいったか、ぜんぜんおぼえていないんです。', 'Tăng hai đã đi đâu vậy? - Vì say nên tôi chẳng nhớ là đã đi đâu cả.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND g.pattern = '～か、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'A：二次会はどこへ行きましたか？ B：酔っていたので、どこへ行ったか、全然覚えていないんです。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～かどうか～', 'Có ~ hay không (lồng câu nghi vấn không có từ để hỏi)', 'Thể thường ＋ かどうか、～。 (Aな/N だ bỏ だ)', 'Lồng câu nghi vấn không chứa từ để hỏi vào trong câu văn khác.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～かどうか～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ボランティアに参加するかどうか、まだ決めていません。', 'ボランティアにさんかするかどうか、まだきめていません。', 'Tôi vẫn chưa quyết định có tham gia tình nguyện hay không.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND g.pattern = '～かどうか～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ボランティアに参加するかどうか、まだ決めていません。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'その話は本当かどうか、わかりません。', 'そのはなしはほんとうかどうか、わかりません。', 'Tôi không biết chuyện đó có thật hay không.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND g.pattern = '～かどうか～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'その話は本当かどうか、わかりません。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'まちがいがないかどうか、調べてください。', 'まちがいがないかどうか、しらべてください。', 'Hãy tìm hiểu xem có sai sót gì không.', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND g.pattern = '～かどうか～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'まちがいがないかどうか、調べてください。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～てみます', 'Thử làm V', 'Vてみます。', 'Thử làm một hành động nào đó xem kết quả thế nào.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～てみます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'このくつは合うかどうか、はいてみてもいいですか？', 'このくつはあうかどうか、はいてみてもいいですか？', 'Đôi giày này tôi đi thử xem có vừa không được không ạ?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND g.pattern = '～てみます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'このくつは合うかどうか、はいてみてもいいですか？' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '京都へ行ってみたいです。', 'きょうとへいってみたいです。', 'Tôi muốn thử đi Kyoto.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND g.pattern = '～てみます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '京都へ行ってみたいです。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Nをいただきます', 'Tôi nhận được vật N từ người trên', '～に Nをいただきます。', 'Tôi (người thân) nhận được vật N từ người trên. いただきます là khiêm nhường ngữ của もらいます. Thể hiện sự biết ơn đến người trên.', 'Khiêm nhường ngữ của もらいます', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Nをいただきます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私は社長にお土産をいただきました。', 'わたしはしゃちょうにおみやげをいただきました。', 'Tôi nhận được quà đặc sản từ giám đốc.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = 'Nをいただきます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私は社長にお土産をいただきました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '先生に本をいただきました。', 'せんせいにほんをいただきました。', 'Tôi nhận sách từ giáo viên.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = 'Nをいただきます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '先生に本をいただきました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Nをくださいます', 'Người trên cho tôi vật N', '～は／が［私に］Nをくださいます。', 'Người trên cho tôi (người thân) vật N. くださいます là tôn kính ngữ của くれます. Thể hiện sự biết ơn đến người trên.', 'Tôn kính ngữ của くれます', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Nをくださいます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '社長は（私に）お土産をくださいました。', 'しゃちょうは（わたしに）おみやげをくださいました。', 'Giám đốc đã tặng quà cho tôi.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = 'Nをくださいます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '社長は（私に）お土産をくださいました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '先生は（私に）本をくださいました。', 'せんせいは（わたしに）ほんをくださいました。', 'Thầy giáo tặng cho tôi cuốn sách.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = 'Nをくださいます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '先生は（私に）本をくださいました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～をやります', 'Tôi cho người dưới, động thực vật cái gì đó', '～に Nをやります。', 'Tôi cho người dưới / động thực vật vật N. Khi người nói cho người dưới/ động thực vật cái gì đó. あげます thay cho やります khi muốn thể hiện sự lịch sự.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～をやります');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '（私は）花に水をやります。', '（わたしは）はなにみずをやります。', 'Tôi tưới nước cho hoa.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '～をやります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '（私は）花に水をやります。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '（私は）子どもにおもちゃをやりました（あげました）。', '（わたしは）こどもにおもちゃをやりました（あげました）。', 'Tôi cho con đồ chơi.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '～をやります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '（私は）子どもにおもちゃをやりました（あげました）。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～ていただきます', 'Được ai đó (người trên) làm ~ cho', '～に Vていただきます。', 'Được ai đó làm ～ cho. いただきます là khiêm nhường ngữ của もらいます. Thể hiện sự biết ơn khi được người trên làm cho điều gì đó.', NULL, 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～ていただきます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私は先生に漢字の間違いを直していただきました。', 'わたしはせんせいにかんじのまちがいをなおしていただきました。', 'Tôi đã được thầy giáo sửa cho lỗi sai của chữ Kanji.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '～ていただきます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私は先生に漢字の間違いを直していただきました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '先輩に仕事について説明していただきました。', 'せんぱいにしごとについてせつめいしていただきました。', 'Tôi được tiền bối giải thích cho về công việc.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '～ていただきます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '先輩に仕事について説明していただきました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '〜てくださいます', 'Người trên làm gì đó cho tôi', '～が [私に] Vてくださいます。', 'Ai đó làm ~ cho tôi. くださいます là tôn kính ngữ của くれます. Thể hiện sự biết ơn khi người trên làm gì đó cho.', NULL, 5 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '〜てくださいます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '先生が私に英語を教えてくださいました。', 'せんせいがわたしにえいごをおしえてくださいました。', 'Thầy giáo đã dạy tiếng Anh cho tôi.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '〜てくださいます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '先生が私に英語を教えてくださいました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '部長が私のレポートを直してくださいました。', 'ぶちょうがわたしのレポートをなおしてくださいました。', 'Trưởng phòng đã sửa báo cáo giúp tôi.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '〜てくださいます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '部長が私のレポートを直してくださいました。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '先輩が私を空港まで送ってくださいました。', 'せんぱいがわたしをくうこうまでおくってくださいました。', 'Tiền bối đã tiễn tôi tới sân bay.', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '〜てくださいます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '先輩が私を空港まで送ってくださいました。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～てやります', 'Tôi làm ~ cho người dưới, động thực vật', '～に Vてやります。', 'Tôi làm ~ cho người dưới, động thực vật.', NULL, 6 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～てやります');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私は孫に英語を教えてやりました（あげました）。', 'わたしはまごにえいごをおしえてやりました（あげました）。', 'Tôi dạy tiếng Anh cho cháu.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '～てやります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私は孫に英語を教えてやりました（あげました）。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私は子どもを公園へ連れて行ってやりました。', 'わたしはこどもをこうえんへつれていってやりました。', 'Tôi dắt con ra công viên.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '～てやります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私は子どもを公園へ連れて行ってやりました。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '私は息子の宿題を見てやりました（あげました）。', 'わたしはむすこのしゅくだいをみてやりました（あげました）。', 'Tôi xem bài tập về nhà cho con trai.', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '～てやります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '私は息子の宿題を見てやりました（あげました）。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～てくださいませんか', 'Làm ơn hãy làm ~ cho tôi (nhờ vả lịch sự)', 'Vてくださいませんか。', 'Làm ơn hãy làm ~ cho tôi. Đây là cách yêu cầu, nhờ vả lịch sự hơn so với ～てください nhưng không lịch sự bằng ～ていただけませんか.', NULL, 7 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～てくださいませんか');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'もう少しゆっくり話してくださいませんか。', 'もうすこしゆっくりはなしてくださいませんか。', 'Làm ơn hãy nói chậm lại một chút.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '～てくださいませんか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'もう少しゆっくり話してくださいませんか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'この漢字の読み方を教えてくださいませんか。', 'このかんじのよみかたをおしえてくださいませんか。', 'Làm ơn chỉ giúp tôi cách đọc chữ Hán này được không ạ?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND g.pattern = '～てくださいませんか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'この漢字の読み方を教えてくださいませんか。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Vる／Nの＋ために、～', 'Để / Vì (nhằm mục đích gì), thì làm ~', 'Vる／Nの＋ために、～', 'Mẫu câu diễn tả việc làm gì đó để nhằm mục đích gì. Nのために: làm gì đó vì lợi ích của đối tượng N.', NULL, 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 42 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vる／Nの＋ために、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '車を買うために、貯金します。', 'くるまをかうために、ちょきんします。', 'Tôi sẽ tiết kiệm để mua xe ô tô.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 42 AND g.pattern = 'Vる／Nの＋ために、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '車を買うために、貯金します。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '家族のために、一生懸命働いています。', 'かぞくのために、いっしょうけんめいはたらいています。', 'Tôi nỗ lực làm việc vì gia đình.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 42 AND g.pattern = 'Vる／Nの＋ために、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '家族のために、一生懸命働いています。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Vるのに/ Nに～', 'Dùng cho việc gì / Để làm gì thì mất...', 'Vるのに／Nに ＋ 使う/便利だ/役に立つ/かかる...', 'Biểu thị mục đích sử dụng hoặc đánh giá. Vế sau hay dùng: 使います、いいです、便利です、役に立ちます、～かかります,... để biểu thị mục đích sử dụng hoặc đánh giá.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 42 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vるのに/ Nに～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ミキサーは材料を混ぜるのに使います。', 'ミキサーはざいりょうをまぜるのにつかいます。', 'Cái máy xay dùng để trộn nguyên liệu.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 42 AND g.pattern = 'Vるのに/ Nに～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ミキサーは材料を混ぜるのに使います。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'このレポートを書くのに1時間かかりました。', 'このレポートをかくのに1じかんかかりました。', 'Tôi đã mất 1 tiếng cho việc viết báo cáo.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 42 AND g.pattern = 'Vるのに/ Nに～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'このレポートを書くのに1時間かかりました。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～そうです', 'Trông có vẻ ~ (phán đoán qua thị giác)', 'Vます(bỏ ます)／Aい(bỏ い)／Aな(bỏ な) ＋ そうです。', 'Diễn tả phán đoán, cảm giác qua vẻ bề ngoài trực tiếp rằng một trạng thái hoặc hành động sắp xảy ra.', NULL, 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 43 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～そうです');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '曇りですね。もうすぐ雨が降りそうですね。', 'くもりですね。もうすぐあめがふりそうですね。', 'Nhiều mây nhỉ. Trời có vẻ như sắp mưa rồi.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 43 AND g.pattern = '～そうです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '曇りですね。もうすぐ雨が降りそうですね。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'このカレーはおいしそうですね。', 'このカレーはおいしそうですね。', 'Món cà ri này có vẻ ngon nhỉ.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 43 AND g.pattern = '～そうです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'このカレーはおいしそうですね。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Vてきます', 'Đi đâu đó làm gì rồi quay lại', 'Vてきます。', 'Diễn tả hành động đi làm việc gì đó rồi quay lại vị trí ban đầu.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 43 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vてきます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'スーパーでジュースを買ってきます。', 'スーパーでジュースをかってきます。', 'Tôi đi mua nước hoa quả ở siêu thị rồi quay lại.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 43 AND g.pattern = 'Vてきます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'スーパーでジュースを買ってきます。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '台所からはさみを取ってきます。', 'だいどころからはさみをとってきます。', 'Tôi lấy kéo ở nhà bếp rồi sẽ quay lại.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 43 AND g.pattern = 'Vてきます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '台所からはさみを取ってきます。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ちょっと銀行へ行って来ます。', 'ちょっとぎんこうへいってきます。', 'Tôi đi ngân hàng một chút rồi quay lại.', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 43 AND g.pattern = 'Vてきます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ちょっと銀行へ行って来ます。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～すぎます', 'Quá ~ (vượt quá mức độ cần thiết)', 'Vます(bỏ ます)／Aい(bỏ い)／Aな(bỏ な) ＋ すぎます。', 'Biểu thị sự vượt quá mức độ cần thiết của một hành vi hoặc trạng thái. Thường dùng trong trường hợp không muốn những điều đó xảy ra. すぎます là động từ nhóm II.', 'Quá ~. すぎます là động từ nhóm II.', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～すぎます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'お酒を飲みすぎて、頭がいたくなりました。', 'おさけをのみすぎて、あたまがいたくなりました。', 'Vì tôi uống rượu quá nhiều nên tôi bị đau đầu.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND g.pattern = '～すぎます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'お酒を飲みすぎて、頭がいたくなりました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'このくつは小さすぎて、はけないよ。', 'このくつはちいさすぎて、はけないよ。', 'Đôi giày này quá nhỏ, tôi không xỏ vào được.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND g.pattern = '～すぎます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'このくつは小さすぎて、はけないよ。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Vます＋にくい／やすい', 'Khó / Dễ thực hiện hành động V', 'Vます(bỏ ます) ＋ にくいです／やすいです。', 'Khó/ dễ ~. V có ý chí: dễ/ khó thực hiện hành động V. V không ý chí: dễ/ khó xảy ra việc V.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Vます＋にくい／やすい');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '第8課の漢字は簡単で、覚えやすいです。', 'だい8かのかんじはかんたんで、おぼえやすいです。', 'Hán tự bài 8 đơn giản nên dễ nhớ.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND g.pattern = 'Vます＋にくい／やすい' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '第8課の漢字は簡単で、覚えやすいです。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'このくつは小さすぎて、歩きにくいです。', 'このくつはちいさすぎて、あるきにくいです。', 'Đôi giày này quá nhỏ nên khó đi bộ.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND g.pattern = 'Vます＋にくい／やすい' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'このくつは小さすぎて、歩きにくいです。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'N/ Aなに/ Aいく＋します', 'Làm cho ~ trở nên ~ (tác động làm biến đổi trạng thái)', 'Nに / Aなに / Aいく ＋ します。', 'Làm cho ~ trở nên ~. Diễn tả hành động làm biến đổi một sự vật, sự việc sang một trạng thái nào đó.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'N/ Aなに/ Aいく＋します');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '自分の部屋をきれいにします。', 'じぶんのへやをきれいにします。', 'Tôi sẽ làm sạch căn phòng của mình.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND g.pattern = 'N/ Aなに/ Aいく＋します' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '自分の部屋をきれいにします。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'テレビの音を小さくしてください。', 'テレビのおとをちいさくしてください。', 'Hãy giảm nhỏ tiếng ti vi.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND g.pattern = 'N/ Aなに/ Aいく＋します' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'テレビの音を小さくしてください。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Nにします', 'Chọn N / Quyết định chọn N', 'Nにします。', 'Chọn N. Đưa ra lựa chọn, quyết định thứ gì đó. Thường dùng khi đi du lịch, gọi đồ ở nhà hàng,…', NULL, 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Nにします');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'このカレーにします。', 'このカレーにします。', 'Tôi chọn món cà ri này.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND g.pattern = 'Nにします' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'このカレーにします。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '旅行の出発は明日にしましょう。', 'りょこうのしゅっぱつはあしたにしましょう。', 'Chúng ta quyết định chuyến du lịch sẽ xuất phát vào ngày mai nhé.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND g.pattern = 'Nにします' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '旅行の出発は明日にしましょう。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～場合、～', 'Trong trường hợp (vế 1), thì (vế 2)', 'V thể thường / Aい / Aな / Nの ＋ 場合(は)、～', 'Trong trường hợp (vế 1), thì (vế 2). Nêu lên một tình huống giả định hoặc có thể xảy ra và cách xử lý tương ứng.', NULL, 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 45 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～場合、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'せきが出る場合は、この薬を飲んでください。', 'せきがでるばあいは、このくすりをのんでください。', 'Trường hợp bị ho thì hãy uống thuốc này nhé.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 45 AND g.pattern = '～場合、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'せきが出る場合は、この薬を飲んでください。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '時間に遅れる場合は、先生に連絡してください。', 'じかんにおくれるばあいは、せんせいにれんらくしてください。', 'Trường hợp muộn giờ thì hãy liên hệ với giáo viên.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 45 AND g.pattern = '～場合、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '時間に遅れる場合は、先生に連絡してください。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～のに、～', 'Mặc dù (vế 1), nhưng mà (vế 2)', 'Thể thường ＋ のに、～。 (Aな/N だ→な)', 'Mặc dù (vế 1), nhưng mà (vế 2). Diễn tả sự bất ngờ, thất vọng hoặc trách móc khi kết quả trái ngược với dự đoán thông thường.', 'Đuôi câu thể hiện sự bất ngờ, thất vọng', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 45 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～のに、～');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ご飯を食べたのに、もうおなかがすいた。', 'ごはんをたべたのに、もうおなかがすいた。', 'Tôi đã ăn cơm rồi thế mà đã lại đói bụng rồi.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 45 AND g.pattern = '～のに、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ご飯を食べたのに、もうおなかがすいた。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'よく勉強したのに、結果がよくなかった。', 'よくべんきょうしたのに、けっかがよくなかった。', 'Tôi đã học rất chăm chỉ ấy vậy mà kết quả lại không tốt.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 45 AND g.pattern = '～のに、～' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'よく勉強したのに、結果がよくなかった。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～ところです', 'Đang chuẩn bị làm / Đang làm / Vừa mới làm xong', 'Vる／Vている／Vた ＋ ところです。', '- Vる＋ところです: Sắp sửa, chuẩn bị làm việc gì đó.
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'これからシャワーをあびるところです。', 'これからシャワーをあびるところです。', 'Tôi chuẩn bị đi tắm.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND g.pattern = '～ところです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'これからシャワーをあびるところです。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'たったいまバスが出たところです。', 'たったいまバスがでたところです。', 'Xe buýt vừa khởi hành xong.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND g.pattern = '～ところです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'たったいまバスが出たところです。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～ばかりです', 'Vừa mới làm gì (theo cảm nhận chủ quan)', 'Vた ＋ ばかりです。', 'Diễn tả hành động vừa mới xảy ra chưa lâu theo cảm nhận tâm lý của người nói (thời gian thực tế có thể đã trôi qua một lúc hoặc nhiều ngày).', 'Mang tính chủ quan của người nói, khác với ところです chỉ khoảnh khắc vừa xong tức thì', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～ばかりです');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '１か月前にかれに会ったばかりです。', '１かげつまえにかれにあったばかりです。', 'Tôi mới gặp anh ấy một tháng trước.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND g.pattern = '～ばかりです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '１か月前にかれに会ったばかりです。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '日本に来たばかりなので、わからないことがたくさんある。', 'にほんにきたばかりなので、わからないことがたくさんある。', 'Vì mới đến Nhật nên có nhiều thứ tôi chưa biết.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND g.pattern = '～ばかりです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '日本に来たばかりなので、わからないことがたくさんある。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～はずです', 'Chắc chắn là ~ (phán đoán có căn cứ)', 'Thể thường ＋ はずです。 (Aな だ→な, N だ→の)', 'Biểu thị sự phán đoán có cơ sở và độ chắc chắn cao của người nói.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～はずです');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'リンさんはどくしんのはずです。', 'リンさんはどくしんのはずです。', 'Chắc chắn là cô Linh độc thân.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND g.pattern = '～はずです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'リンさんはどくしんのはずです。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '飛行機は３時に着くはずです。', 'ひこうきは３じにつくはずです。', 'Chắc chắn là máy bay sẽ đến nơi lúc 3 giờ.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND g.pattern = '～はずです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '飛行機は３時に着くはずです。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～そうです', 'Nghe nói là ~ (truyền đạt thông tin)', 'Thể thường ＋ そうです。', 'Dùng để truyền đạt lại thông tin nghe được từ nguồn khác mà không thêm ý kiến cá nhân. Thường đi kèm với ～によると (theo như...). Khác với そうです phán đoán ở Bài 43 (Vます/A bỏ い,な).', 'Đi với thể thông thường. Thường đi kèm ～によると.', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～そうです');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '天気予報によると、あした雨が降るそうです。', 'てんきよほうによると、あしたあめがふるそうです。', 'Theo dự báo thời tiết, nghe nói ngày mai trời có mưa.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND g.pattern = '～そうです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '天気予報によると、あした雨が降るそうです。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ニュースによると、昨日事故があったそうです。', 'ニュースによると、きのうじこがあったそうです。', 'Theo như bản tin, nghe nói hôm qua đã có tai nạn.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND g.pattern = '～そうです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ニュースによると、昨日事故があったそうです。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, '～ようです', 'Hình như là ~ (phán đoán qua giác quan, dấu hiệu)', 'Thể thường ＋ ようです。 (Aな だ→な, N だ→の)', 'Phán đoán dựa trên cảm giác hoặc chứng cứ gián tiếp (âm thanh, mùi vị, dấu hiệu quan sát được).', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～ようです');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'うるさいですね。けんかしているようです。', 'うるさいですね。けんかしているようです。', 'Ồn ào nhỉ. Hình như là đang có cãi nhau.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND g.pattern = '～ようです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'うるさいですね。けんかしているようです。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '電気がついていないので、留守のようですね。', 'でんきがついていないので、るすのようですね。', 'Vì đèn không sáng nên hình như là người ta đi vắng rồi.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND g.pattern = '～ようです' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '電気がついていないので、留守のようですね。' AND ge2.sort_order = 2);
