INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'SはNをVさせる・SはNにVさせる', 'Bắt / cho phép ai đó làm việc ~', 'Sは Nを V(nội động từ)させる
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '部長はナムさんを日本へ出張させました。', 'ぶちょうはナムさんをにほんへしゅっちょうさせました。', 'Trưởng phòng cho anh Nam sang Nhật Bản công tác.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND g.pattern = 'SはNをVさせる・SはNにVさせる' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '部長はナムさんを日本へ出張させました。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '母は子どもに野菜をたくさん食べさせます。', 'はははこどもにやさいをたくさんたべさせます。', 'Mẹ bắt con ăn nhiều rau.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND g.pattern = 'SはNをVさせる・SはNにVさせる' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '母は子どもに野菜をたくさん食べさせます。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Ｖさせていただけませんか', 'Làm ơn cho phép tôi làm ~ (xin phép lịch sự)', 'V(sai khiến thể て) ＋ いただけませんか。', 'Làm ơn cho phép tôi làm ~. Mẫu câu xin phép người trên để cho mình làm gì đó một cách lịch sự, khiêm nhường.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Ｖさせていただけませんか');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '病気なので、休ませていただけませんか。', 'びょうきなので、やすませていただけませんか。', 'Vì tôi bị ốm nên anh có thể cho phép tôi nghỉ có được không?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND g.pattern = 'Ｖさせていただけませんか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '病気なので、休ませていただけませんか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'すみません、この本を使わせていただけませんか。', 'すみません、このほんをつかわせていただけませんか。', 'Xin lỗi, bạn có thể cho phép tôi sử dụng cuốn sách này được không?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND g.pattern = 'Ｖさせていただけませんか' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'すみません、この本を使わせていただけませんか。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'Ｖられます', '(Người trên) làm việc ~ (tôn kính ngữ chia dạng bị động)', 'Sは Vられます。', '(Người trên) làm việc ~. Đây là động từ thể tôn kính, cách chia giống động từ thể bị động. Không sử dụng để nói về hành động của người trong gia đình.', 'Chia giống thể bị động. Không dùng cho hành động của người trong gia đình.', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'Ｖられます');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '社長はあした出張されます。', 'しゃちょうはあしたしゅっちょうされます。', 'Giám đốc sẽ đi công tác vào ngày mai.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'Ｖられます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '社長はあした出張されます。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '先生は本を読まれています。', 'せんせいはほんをよまれています。', 'Thầy giáo đang đọc sách.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'Ｖられます' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '先生は本を読まれています。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'おVになります', '(Người trên) làm ~ (tôn kính mức độ cao hơn)', 'SはおV(bỏ ます)になります。', '(Người trên) làm ~. Mức độ tôn kính cao hơn mẫu chia giống thể bị động. Không dùng cho những động từ trước ます chỉ có 1 âm tiết hoặc động từ nhóm III. Không sử dụng để nói về hành động của người trong gia đình.', 'Mức độ tôn kính cao hơn Vられます', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'おVになります');
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '社長は 音楽をお聞きになっています。', 'しゃちょうはおんがくをおききになっています。', 'Giám đốc đang nghe nhạc.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'おVになります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '社長は 音楽をお聞きになっています。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '先生は本をお読みになっています。', 'せんせいはほんをおよみになっています。', 'Thầy giáo đang đọc sách.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'おVになります' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '先生は本をお読みになっています。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'とくべつな尊敬語（そんけいご）', 'Tôn kính ngữ đặc biệt (các động từ bất quy tắc)', '- いきます、きます、います → いらっしゃいます (いらっしゃる)
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '先生は教室にいらっしゃいます。', 'せんせいはきょうしつにいらっしゃいます。', 'Thầy giáo ở lớp học.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'とくべつな尊敬語（そんけいご）' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '先生は教室にいらっしゃいます。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '部長は何とおっしゃいましたか。', 'ぶちょうはなんとおっしゃいましたか。', 'Trưởng phòng đã nói gì vậy ạ?', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'とくべつな尊敬語（そんけいご）' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '部長は何とおっしゃいましたか。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'どうぞ、召し上がってください。', 'どうぞ、めしあがってください。', 'Mời anh/chị dùng (ăn/uống ạ).', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'とくべつな尊敬語（そんけいご）' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'どうぞ、召し上がってください。' AND ge2.sort_order = 3);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'お／ご～ください', 'Xin hãy làm ~ (yêu cầu tôn kính)', 'お／ご～ください。
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '少々お待ちください。', 'しょうしょうおまちください。', 'Anh/ chị  chờ một chút.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'お／ご～ください' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '少々お待ちください。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ご利用ください。', 'ごりようください。', 'Anh/ chị hãy sử dụng.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'お／ご～ください' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ご利用ください。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'お/ご+ N/A', 'Tiền tố kính ngữ お／ご gắn trước Danh từ hoặc Tính từ', 'お/ご + N/A', 'Thêm 「お」 hoặc 「ご」 trước danh từ, tính từ, hay phó từ để thể hiện sự tôn kính đến chủ sở hữu danh từ đó hay người trong trạng thái đó.
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'お国、お暇、お忙しい、お名前、…', 'おくに、おひま、おいそがしい、おなまえ、…', 'Đất nước, thời gian rảnh, bận rộn, tên (của quý vị)...', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'お/ご+ N/A' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'お国、お暇、お忙しい、お名前、…' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'ご家族、ご両親、ご熱心、…', 'ごかぞく、ごりょうしん、ごねっしん、…', 'Gia đình, bố mẹ, sự nhiệt tình (của quý vị)...', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND g.pattern = 'お/ご+ N/A' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'ご家族、ご両親、ご熱心、…' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'お／ご～します', '(Tôi xin phép) làm ~ giúp người trên (khiêm nhường ngữ)', 'お／ご～します。
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '重そうですね。お持ちしましょうか。', 'おもそうですね。おもちしましょうか。', 'Trông có vẻ nặng nhỉ. Tôi tôi mang giúp anh/ chị nhé?', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 50 AND g.pattern = 'お／ご～します' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '重そうですね。お持ちしましょうか。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'もう一度ご説明します。', 'もういちどごせつめいします。', 'Tôi xin phép giải thích thêm một lần nữa.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 50 AND g.pattern = 'お／ご～します' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'もう一度ご説明します。' AND ge2.sort_order = 2);
INSERT INTO grammars (lesson_id, pattern, meaning, usage_text, explanation, notes, sort_order) SELECT ls.id, 'とくべつな謙譲語（けんじょうご）', 'Khiêm nhường ngữ đặc biệt (các động từ bất quy tắc)', '- いきます、きます → まいります (まいる)
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'はじめまして。田中と申します。', 'はじめまして。たなかともうします。', 'Rất hân hạnh được gặp. Tôi tên là Tanaka.', NULL, 1 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 50 AND g.pattern = 'とくべつな謙譲語（けんじょうご）' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'はじめまして。田中と申します。' AND ge2.sort_order = 1);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, '社長にお菓子をいただきました。', 'しゃちょうにおかしをいただきました。', 'Tôi đã nhận được bánh kẹo từ giám đốc.', NULL, 2 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 50 AND g.pattern = 'とくべつな謙譲語（けんじょうご）' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = '社長にお菓子をいただきました。' AND ge2.sort_order = 2);
INSERT INTO grammar_examples (grammar_id, japanese, furigana, translation, explanation, sort_order) SELECT g.id, 'この書類を拝見してもよろしいですか。', 'このしょるいをはいけんしてもよろしいですか。', 'Tôi có thể xem qua tài liệu này được không ạ?', NULL, 3 FROM grammars g JOIN lessons ls ON g.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 50 AND g.pattern = 'とくべつな謙譲語（けんじょうご）' AND NOT EXISTS (SELECT 1 FROM grammar_examples ge2 WHERE ge2.grammar_id = g.id AND ge2.japanese = 'この書類を拝見してもよろしいですか。' AND ge2.sort_order = 3);
