-- V6__add_n4_grammar.sql
-- Thêm 89 mẫu ngữ pháp N4 và 192 câu ví dụ từ nguồn Ngữ Pháp N4.pdf

-- 1. Đảm bảo Level N4 tồn tại
SELECT 'N4', 'N4', 'Trình độ N4 - Sơ trung cấp', 2, TRUE
WHERE NOT EXISTS (SELECT 1 FROM levels WHERE code = 'N4');

-- 2. Đảm bảo 25 bài học N4 (Bài 26 đến Bài 50) tồn tại

-- 3. Chèn ngữ pháp N4 và ví dụ theo từng bài
-- ==========================================
-- Bài 26: 3 mẫu ngữ pháp
-- ==========================================
- Muốn được cung cấp thêm thông tin (ở đâu, bao giờ, bao nhiêu…)
- Muốn hỏi lý do hoặc giải thích về việc gì đó.', 'Đuôi câu: だ → な', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～んですか');
-- ==========================================
-- Bài 27: 5 mẫu ngữ pháp
-- ==========================================
Nhóm 2: ～ます → ～られます
Nhóm 3: ～します → ～できます, 来ます → 来られます', '- Cách chia thể khả năng:
+ Nhóm 1:まちます→まてます, よびます→よべます, かきます→かけます, およぎます→およげます, はなします→はなせます
+ Nhóm 2: たべます→たべられます, かります→かりられます
+ Nhóm 3: べんきょうします→べんきょうできます, 来ます(きます)→来られます(こられます)
- Diễn tả năng lực của chủ thể (có thể làm ~) hoặc khả năng thực hiện hành động trong hoàn cảnh nào đó.
- Chú ý:
+ Động từ khả năng biến đổi như động từ nhóm II.
+ Các động từ không mang tính hành động (あります、います、…) hoặc tự thân đã mang nghĩa khả năng (わかります、できます、…) thì không chia sang thể khả năng.
+ Trợ từ を → が, còn các trợ từ khác thì giữ nguyên.', 'Động từ khả năng đóng vai trò như động từ nhóm II. Trợ từ を đổi thành が.', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～可能形（かのうけい）');
-- ==========================================
-- Bài 28: 3 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 29: 4 mẫu ngữ pháp
-- ==========================================
Tha động từ: N を V(tha động từ)', 'Tự động từ: Diễn tả chuyển động, trạng thái tự thân của sự vật mà không cần tác nhân trực tiếp, đi với trợ từ が.
Tha động từ: Diễn tả hành động có chủ ý của người/tác nhân tác động lên đối tượng, đi với trợ từ を.
Các cặp động từ tiêu biểu:
- ドアが開きます (Cửa mở) / ドアを開けます (Mở cửa)
- ドアが閉まります (Cửa đóng) / ドアを閉めます (Đóng cửa)
- 電気がつきます (Đèn sáng) / 電気をつけます (Bật đèn)
- 電気が消えます (Đèn tắt) / 電気を消します (Tắt đèn)
- 車が止まります (Xe dừng) / 車を止めます (Dừng xe)', NULL, 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 29 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '自動詞・他動詞');
-- ==========================================
-- Bài 30: 4 mẫu ngữ pháp
-- ==========================================
まだVていません：Vẫn chưa làm V.', NULL, 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 30 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'まだ～');
-- ==========================================
-- Bài 31: 4 mẫu ngữ pháp
-- ==========================================
Nhóm 2: ～ます → ～よう
Nhóm 3: します → しよう, 来ます(きます) → 来よう(こよう)', '- Cách chia thể ý định:
+ Nhóm 1: いきます→いこう, まちます→まとう, よみます→よもう, とります→とろう
+ Nhóm 2: ねます→ねよう, たべます→たべよう, みます→みよう
+ Nhóm 3: べんきょうします→べんきょうしよう, もってきます→もってこよう
- Thể ý định là thể thông thường của thể rủ rê ～ましょう trong văn thân mật.', 'Là thể thông thường của ～ましょう', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 31 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '意向形（いこうけい）');
-- ==========================================
-- Bài 32: 3 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 33: 6 mẫu ngữ pháp
-- ==========================================
Cấm chỉ: Động từ thể từ điển (Vる) ＋ な', '命令形(Thể mệnh lệnh): Hãy làm V.
禁止形(Thể cấm chỉ): Cấm làm V.
Cả hai thể đều mang sắc thái mạnh, áp đặt, thường sẽ là nam giới (người trên) nói với người dưới, bố nói với con, bạn bè nam giới thân thiết nói với nhau, tình huống khẩn cấp, hiệu lệnh.
Trong cổ vũ thể thao thì nữ cũng có thể dùng.', NULL, 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '禁止形・命令形');
-- ==========================================
-- Bài 34: 4 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 35: 4 mẫu ngữ pháp
-- ==========================================
- Nhóm 1: ～iます → ～eば
- Nhóm 2: ～ます → ～れば
- Nhóm 3: きます → くれば, します → すれば
Tính từ và Danh từ:
- Aい ＋ ければ (＊いい → よければ)
- Aな ＋ なら
- N ＋ なら
Dạng phủ định:
- V: Vない ＋ ければ
- Aい: Aくない ＋ ければ
- Aな・N: Aな・N ＋ じゃなければ', '- Động từ: いきます→いけば, まちます→まてば, やすみます→やすめば, よみます→よめば, とります→とれば; ねます→ねれば, たべます→たべれば, かります→かりれば, みます→みれば; もってきます→もってくれば, べんきょうします→べんきょうすれば
- Tính từ đuôi i: たのしい→たのしければ, おいしい→おいしければ, やすい→やすければ, たかい→たかければ (＊いい→よければ)
- Tính từ đuôi na & Danh từ: ひま→ひまなら, しずか→しずかなら, げんき→げんきなら; せんせい→せんせいなら, りょこう→りょこうなら
- Dạng phủ định: いかない→いかなければ, もたない→もたなければ; たのしくない→たのしくなければ; げんきじゃなければ, せんせいじゃなければ', 'Bảng tổng hợp quy tắc chia thể điều kiện', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '条件形 (じょうけんけい)');
-- ==========================================
-- Bài 36: 3 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 37: 5 mẫu ngữ pháp
-- ==========================================
Nhóm 2: ～ます → ～られます
Nhóm 3: きます → こられます, します → されます', '- Nhóm 1: いきます→いかれます, まちます→またれます, よみます→よまれます, とります→とられます
- Nhóm 2: ねます→ねられます, たべます→たべられます, かります→かりられます, みます→みられます
- Nhóm 3: 来ます(きます)→来られます(こられます), します→されます, もってきます→もってこられます, べんきょうします→べんきょうされます', 'Bảng tổng hợp quy tắc chia thể bị động', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 37 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '受身形 (うけみけい)');
-- ==========================================
-- Bài 38: 5 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 39: 3 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 40: 3 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 41: 7 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 42: 2 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 43: 2 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 44: 4 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 45: 2 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 46: 3 mẫu ngữ pháp
-- ==========================================
- Vている＋ところです: Đang trong quá trình thực hiện hành động.
- Vた＋ところです: Vừa mới hoàn thành hành động tức thì.', NULL, 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '～ところです');
-- ==========================================
-- Bài 47: 2 mẫu ngữ pháp
-- ==========================================
-- ==========================================
-- Bài 48: 3 mẫu ngữ pháp
-- ==========================================
Nhóm 2: ～ます → ～させます
Nhóm 3: きます → こさせます, します → させます', '- Nhóm 1: いきます→いかせます, まちます→またせます, やすみます→やませます, よみます→よませます, とります→とらせます
- Nhóm 2: ねます→ねさせます, たべます→たべさせます, かります→かりさせます, みます→みさせます
- Nhóm 3: 来ます(きます)→こさせます, します→させます, もってきます→もってこさせます, べんきょうします→べんきょうさせます', 'Bảng tổng hợp quy tắc chia thể sai khiến', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = '使役 (しえき)');
Sは Nに N(vật)を V(ngoại động từ)させる', '- Sは Nを Vさせる: sử dụng với V (nội động từ).
- Sは Nに Vさせる: sử dụng với V (ngoại động từ).
Bắt/ cho phép ai đó làm việc ~.', NULL, 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'SはNをVさせる・SはNにVさせる');
-- ==========================================
-- Bài 49: 5 mẫu ngữ pháp
-- ==========================================
- たべます、のみます → めしあがります (めしあがる)
- いいます → おっしゃいます (おっしゃる)
- みます → ごらんになります (ごらんになる)
- します → なさいます (なさる)
- くれます → くださいます (くださる)
- しっています → ごぞんじです (ごぞんじだ)', 'Bảng các động từ có dạng tôn kính ngữ đặc biệt không theo quy tắc chia thông thường:
- いきます、きます、います → いらっしゃいます (いらっしゃる)
- たべます、のみます → めしあがります (めしあがる)
- いいます → おっしゃいます (おっしゃる)
- みます → ごらんになります (ごらんになる)
- します → なさいます (なさる)
- くれます → くださいます (くださる)
- しっています → ごぞんじです (ごぞんじだ)', 'Bảng tổng hợp các động từ tôn kính ngữ đặc biệt', 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'とくべつな尊敬語（そんけいご）');
- V nhóm I, II: おV(bỏ ます)ください。
- V nhóm III: ごN ください。', 'Xin hãy làm ~. Đây là cách nói tôn kính của: Vてください. V nhóm I, II (trừ động từ có một âm tiết trước ます): おVますください. V nhóm III: ごN ください.', 'Cách nói tôn kính của Vてください', 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'お／ご～ください');
※ Thông thường:
「お」 thường dùng với từ thuần Nhật.
「ご」 thường dùng với từ có gốc Hán.', 'お + từ thuần Nhật / ご + từ gốc Hán', 5 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'お/ご+ N/A');
-- ==========================================
-- Bài 50: 2 mẫu ngữ pháp
-- ==========================================
- V nhóm I, II: おV(bỏ ます)します。
- V nhóm III: ごN します。', 'Thể hiện sự tôn kính với người trên bằng cách khiêm nhường hành động của mình hoặc người ở phía mình. Không sử dụng với các động từ có 1 âm tiết trước ます.', 'Không sử dụng với các động từ có 1 âm tiết trước ます', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 50 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'お／ご～します');
- います → おります (おる)
- たべます、のみます、もらいます → いただきます (いただく)
- いいます → もうします (もうす)
- します → いたします (いたす)
- しっています → ぞんじております
- しりません → ぞんじません
- みます → はいけんします (はいけんする)
- ききます、（うちへ）いきます → うかがいます (うかがう)
- あいます → おめにかかります (おめにかかる)', 'Bảng các động từ có dạng khiêm nhường ngữ đặc biệt không theo quy tắc chia thông thường:
- いきます、きます → まいります (まいる)
- います → おります (おる)
- たべます、のみます、もらいます → いただきます (いただく)
- いいます → もうします (もうす)
- します → いたします (いたす)
- しっています → ぞんじております / しりません → ぞんじません
- みます → はいけんします (はいけんする)
- ききます、（うちへ）いきます → うかがいます (うかがう)
- あいます → おめにかかります (おめにかかる)', 'Bảng tổng hợp các động từ khiêm nhường ngữ đặc biệt', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 50 AND NOT EXISTS (SELECT 1 FROM grammars g2 WHERE g2.lesson_id = ls.id AND g2.pattern = 'とくべつな謙譲語（けんじょうご）');
